struct FTrimeshBVH
{
	using FAABBType = TAABB<FRealSingle, 3>;

	enum class EPerFaceBoundsRepresentation : uint8
	{
		VectorizedFloat = 0,
		Byte
	};

	enum class EVisitorResult
	{
		Stop = 0,
		Continue,
	};

	enum class EFilterResult
	{
		Skip = 0,
		Keep,
	};

	struct alignas(16) FChildData
	{
		FChildData()
			: ChildOrFaceIndex{ INDEX_NONE, INDEX_NONE }
			, FaceCount{ 0, 0 }
		{
		}

		FORCEINLINE int32 GetChildOrFaceIndex(int ChildIndex) const
		{
			return ChildOrFaceIndex[ChildIndex];
		}

		FORCEINLINE int32 GetFaceCount(int ChildIndex) const
		{
			return FaceCount[ChildIndex];
		}

		FORCEINLINE void SetChildOrFaceIndex(int ChildIndex, int32 InChildOrFaceIndex)
		{
			ChildOrFaceIndex[ChildIndex] = InChildOrFaceIndex;
		}

		FORCEINLINE void SetFaceCount(int ChildIndex, int32 InFaceCount)
		{
			FaceCount[ChildIndex] = InFaceCount;
		}

		FORCEINLINE void SetBounds(int ChildIndex, const FAABB3& AABB)
		{
			Bounds[ChildIndex] = FAABBVectorized(AABB);
		}
		FORCEINLINE void SetBounds(int ChildIndex, const TAABB<FRealSingle, 3>& AABB)
		{
			Bounds[ChildIndex] = FAABBVectorized(AABB);
		}

		FORCEINLINE const FAABBVectorized& GetBounds(int ChildIndex) const { return Bounds[ChildIndex]; }

		void Serialize(FArchive& Ar)
		{
			Ar << Bounds[0];
			Ar << ChildOrFaceIndex[0];

	VisitTree(BoundsFilter, FaceVisitor);
}

template <typename SQVisitor>
FORCEINLINE_DEBUGGABLE void Overlap(const FAABBVectorized& AABB, SQVisitor& Visitor) const
{
	const auto BoundsFilter = [&AABB](const FAABBVectorized& Bounds) -> EFilterResult
	{
		const bool bHit = Bounds.Intersects(AABB);
		return bHit ? EFilterResult::Keep : EFilterResult::Skip;
	};

	const auto FaceVisitor = [&Visitor](int32 FaceIndex)
	{
		const bool bContinueVisiting = Visitor.VisitOverlap(FaceIndex);
		return bContinueVisiting ? EVisitorResult::Continue : EVisitorResult::Stop;
	};

	VisitTree(BoundsFilter, FaceVisitor);
}

FORCEINLINE_DEBUGGABLE EVisitorResult VisitFaces(int32 StartIndex, int32 IndexCount, BoundsFilterType& BoundsFilter, FaceVisitorType& FaceVisitor) const
{
	const int32 EndIndex = (StartIndex + IndexCount);  
	for (int32 FaceIndex = StartIndex; FaceIndex < EndIndex; ++FaceIndex)
	{
		if (BoundsFilter(FaceBounds[FaceIndex]) == EFilterResult::Keep)
		{
			if (FaceVisitor(FaceIndex) == EVisitorResult::Stop)
			{
				return EVisitorResult::Stop;
			}
		}
	}
	return EVisitorResult::Continue;
}

		FORCEINLINE_DEBUGGABLE void VisitTree(BoundsFilterType& BoundsFilter, FaceVisitorType& FaceVisitor) const
		{
			if (Nodes.Num() == 0)
			{
				return;
			}
			if (!FaceBounds.IsEmpty())
			{
				VisitTreeImpl<BoundsFilterType, FaceVisitorType, false>(BoundsFilter, FaceVisitor);
			}
			else
			{
				VisitTreeImpl<BoundsFilterType, FaceVisitorType, true>(BoundsFilter, FaceVisitor);
			}
		}
private:
		template <typename BoundsFilterType, typename FaceVisitorType, bool bUseQuantizedBounds>
		FORCEINLINE_DEBUGGABLE void VisitTreeImpl(BoundsFilterType& BoundsFilter, FaceVisitorType& FaceVisitor) const
		{
			TArray<int32, TInlineAllocator<16>> NodeIndexStack;
			NodeIndexStack.Push(0);
			while (NodeIndexStack.Num())
			{
				const int32 NodeIndex = NodeIndexStack.Pop(EAllowShrinking::No);
				check(Nodes.IsValidIndex(NodeIndex));
				const FNode& Node = Nodes[NodeIndex];

				for (int32 ChildIndex = 0; ChildIndex < 2; ++ChildIndex)
				{
					const FChildData& ChildData = Node.Children; 
					const int32 FaceIndex = ChildData.GetChildOrFaceIndex(ChildIndex);
					if (FaceIndex != INDEX_NONE)
					{
						if (BoundsFilter(ChildData.GetBounds(ChildIndex)) == EFilterResult::Keep)
						{
							const uint32 FaceCount = ChildData.GetFaceCount(ChildIndex);
							if (FaceCount > 0)
							{
								if constexpr (!bUseQuantizedBounds)
								{
									if (EVisitorResult::Stop == VisitFaces(FaceIndex, FaceCount, BoundsFilter, FaceVisitor))
									{
										return;
									}
								}
								else
								{
									if (EVisitorResult::Stop == VisitFacesQuantized(ChildData.GetBounds(ChildIndex), FaceIndex, FaceCount, BoundsFilter, FaceVisitor))
									{
										return;
									}
								}
							}
							else
							{
								NodeIndexStack.Push(FaceIndex);
							}
						}
					}
				}
			}

		/// to save storage costs, instead of using the FaceBounds array

private:
		// Array of quantized face bound data; with 6 elements per triangle + one buffer element at the end to allow safe use of vectorized loads
		TArray<uint8> QuantizedFaceBoundData;

		// @return true if the BVH should use quantized bounds -- i.e., if it is not empty and has no FaceBounds
		bool NeedsQuantizedBounds();

		// Set quantized bounds from mesh data
		void InitializeQuantizedBounds(const TParticles<FRealSingle, 3>& Particles, const FTrimeshIndexBuffer& IndexBuffer);

		// Reset face bounds data
		void ResetFaceBounds(int32 NumTris, bool bUseQuantized);

		// Add a new quantized bound
		void AddQuantizedFaceBound(const TAABB<FRealSingle, 3>& NodeBounds, const TAABB<FRealSingle, 3>& TriBounds);	

		// alternate visit faces method, using quantized face bounds
		template <typename BoundsFilterType, typename FaceVisitorType>
		FORCEINLINE_DEBUGGABLE EVisitorResult VisitFacesQuantized(const FAABBVectorized& NodeBounds, int32 StartIndex, int32 IndexCount, BoundsFilterType& BoundsFilter, FaceVisitorType& FaceVisitor) const
		{
			// compute the scale factor to convert quantized uint8 values to relative positions within the node
			constexpr VectorRegister4Float DeQuantFracScale = MakeVectorRegisterFloatConstant(1.f / 255.f, 1.f / 255.f, 1.f / 255.f, 1.f);
			const VectorRegister4Float DeQuantScale = VectorMultiply(VectorSubtract(NodeBounds.GetMax(), NodeBounds.GetMin()), DeQuantFracScale);

			const int32 EndIndex = (StartIndex + IndexCount);
			int32 FaceIndex = StartIndex;
			// Note EndIndex*6 is 1 element *past* the actual quantized bounds data, but should still be valid because we store an extra buffer byte to allow VectorLoadByte4 to be safely used
			checkSlow(IndexCount > 0 && (QuantizedFaceBoundData.IsValidIndex(FaceIndex * 6) && QuantizedFaceBoundData.IsValidIndex(EndIndex * 6)));
			for (const uint8* QBoundPtr = QuantizedFaceBoundData.GetData() + StartIndex * 6; FaceIndex < EndIndex; ++FaceIndex, QBoundPtr += 6)
			{
				if (BoundsFilter(FAABBVectorized(
					VectorMultiplyAdd(DeQuantScale, VectorLoadByte4(&QBoundPtr[0]), NodeBounds.GetMin()),
					VectorMultiplyAdd(DeQuantScale, VectorLoadByte4(&QBoundPtr[3]), NodeBounds.GetMin()))) == EFilterResult::Keep)
				{
					if (FaceVisitor(FaceIndex) == EVisitorResult::Stop)
					{
						return EVisitorResult::Stop;
					}
				}
			}
			return EVisitorResult::Continue;
		}

